346. pub(super) unsafe fn init(bitmap: SparseBitmap) -> Result<(), Error> {
347.     if unlikely(INSTANCE_INIT.load(ORDER)) {
348.         return Err(Error::new(ErrorCode::InvalidArgument, "frame allocator already initialized"));
